<?php
require_once __DIR__.'/../config.php';require_once __DIR__.'/../base/AdminAuth.class.php';require_once __DIR__.'/../base/GameEmailPolicy.class.php';require_once __DIR__.'/../base/NotificationPolicy.class.php';
$s=new Game();$auth=new AdminAuth($s->db_link);if(!$auth->isAuthenticated()){header('Location: /');exit;}$db=$s->db_link;$csrf=$_SESSION['admin_email_csrf']??bin2hex(random_bytes(24));$_SESSION['admin_email_csrf']=$csrf;$message='';$error='';
$db->query("CREATE TABLE IF NOT EXISTS game_email_messages (email_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,from_uid INT NULL,from_address VARCHAR(190) NOT NULL,to_uid INT NULL,to_address VARCHAR(190) NOT NULL,subject VARCHAR(190) NOT NULL,body TEXT NOT NULL,email_type VARCHAR(16) NOT NULL DEFAULT 'system',is_read TINYINT(1) NOT NULL DEFAULT 0,is_deleted TINYINT(1) NOT NULL DEFAULT 0,delivery_status VARCHAR(16) NOT NULL DEFAULT 'queued',created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,sent_at DATETIME NULL,broadcast_id BIGINT UNSIGNED NULL,has_attachments TINYINT(1) NOT NULL DEFAULT 0,KEY idx_game_email_recipient(to_uid,is_deleted,created_at),KEY idx_game_email_queue(delivery_status,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");$db->query("ALTER TABLE game_email_messages ADD COLUMN IF NOT EXISTS broadcast_id BIGINT UNSIGNED NULL, ADD COLUMN IF NOT EXISTS has_attachments TINYINT(1) NOT NULL DEFAULT 0");$db->query("CREATE TABLE IF NOT EXISTS game_mail_broadcasts (broadcast_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,sender_address VARCHAR(190) NOT NULL,subject VARCHAR(190) NOT NULL,body TEXT NOT NULL,recipient_count INT UNSIGNED NOT NULL DEFAULT 0,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");$db->query("CREATE TABLE IF NOT EXISTS game_email_attachments (attachment_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,email_id BIGINT UNSIGNED NOT NULL,uid INT NOT NULL,attachment_type ENUM('currency','item','equipment') NOT NULL,resource_key VARCHAR(64) NULL,asset_key VARCHAR(128) NULL,quantity BIGINT UNSIGNED NOT NULL DEFAULT 1,claimed_at DATETIME NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_mail_attachment(email_id,attachment_type,resource_key,asset_key),KEY idx_mail_attachment_claim(uid,claimed_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
if($_SERVER['REQUEST_METHOD']==='POST'){if(!hash_equals($csrf,(string)($_POST['csrf']??'')))$error='Security validation failed.';elseif(!$auth->isAtLeast('operator'))$error='Operator privileges are required.';else{$action=(string)($_POST['admin_email_action']??'');$subject=GameEmailPolicy::cleanSubject((string)($_POST['subject']??''));$body=GameEmailPolicy::cleanBody((string)($_POST['body']??''));$type=(string)($_POST['attachment_type']??'');$resource=trim((string)($_POST['resource_key']??''));$asset=trim((string)($_POST['asset_key']??''));$qty=(int)($_POST['quantity']??0);$hasAttachment=$type!==''||$resource!==''||$asset!==''||$qty!==0;$validAttachment=!$hasAttachment||GameEmailPolicy::validAttachment($type,$resource,$asset,$qty);if($subject===''||$body===''||!$validAttachment)$error='Provide a subject, body, and valid optional attachment.';else{$root=(string)($_POST['from_address']??GameEmailPolicy::ROOT_ADDRESS);if(!GameEmailPolicy::validAddress($root))$error='Root sender address is invalid.';else if($action==='broadcast'){$db->begin_transaction();$b=$db->prepare('INSERT INTO game_mail_broadcasts(sender_address,subject,body) VALUES(?,?,?)');$b->bind_param('sss',$root,$subject,$body);if(!$b->execute()){$db->rollback();$error='Broadcast creation failed.';}else{$broadcastId=(int)$db->insert_id;$users=$db->query('SELECT uid,email FROM users');$ins=$db->prepare("INSERT INTO game_email_messages(from_uid,from_address,to_uid,to_address,subject,body,email_type,delivery_status,broadcast_id,has_attachments) VALUES(NULL,?,?,?,?,?,'broadcast','queued',?,?)");$att=$db->prepare('INSERT INTO game_email_attachments(email_id,uid,attachment_type,resource_key,asset_key,quantity) VALUES(?,?,?,?,?,?)');$count=0;while($u=$users->fetch_assoc()){$toUid=(int)$u['uid'];$to=GameEmailPolicy::validAddress((string)$u['email'])?$u['email']:('player'.$toUid.'@universecivilization.game');$ins->bind_param('sisssii',$root,$toUid,$to,$subject,$body,$broadcastId,$hasAttachment);if(!$ins->execute()){ $db->rollback();$error='Broadcast delivery failed.';break;}$emailId=(int)$db->insert_id;if($hasAttachment){$att->bind_param('iisssi',$emailId,$toUid,$type,$resource,$asset,$qty);if(!$att->execute()){ $db->rollback();$error='Broadcast attachment failed.';break; }}NotificationPolicy::push($db,$toUid,'broadcast','Server-wide announcement',$subject,'broadcast:'.$broadcastId.':'.$toUid,['broadcast_id'=>$broadcastId,'email_id'=>$emailId]);$count++;}if($error===''){$b2=$db->prepare('UPDATE game_mail_broadcasts SET recipient_count=? WHERE broadcast_id=?');$b2->bind_param('ii',$count,$broadcastId);$b2->execute();$db->commit();$auth->audit('send_global_broadcast','email_network',['broadcast_id'=>$broadcastId,'recipient_count'=>$count]);$message='Broadcast queued for '.$count.' commander(s).';}}}else{$uid=(int)($_POST['to_uid']??0);$user=$db->query("SELECT uname,email FROM users WHERE uid=$uid LIMIT 1");$u=$user?$user->fetch_assoc():null;if(!$u){$error='Recipient UID not found.';}else{$to=GameEmailPolicy::validAddress((string)$u['email'])?$u['email']:('player'.$uid.'@universecivilization.game');$stmt=$db->prepare("INSERT INTO game_email_messages(from_uid,from_address,to_uid,to_address,subject,body,email_type,delivery_status,has_attachments) VALUES(NULL,?,?,?,?,?,'system','queued',?)");$stmt->bind_param('sisssi',$root,$uid,$to,$subject,$body,$hasAttachment);if(!$stmt->execute())$error='Could not queue root email.';else{$emailId=(int)$db->insert_id;if($hasAttachment){$att=$db->prepare('INSERT INTO game_email_attachments(email_id,uid,attachment_type,resource_key,asset_key,quantity) VALUES(?,?,?,?,?,?)');$att->bind_param('iisssi',$emailId,$uid,$type,$resource,$asset,$qty);$att->execute();}NotificationPolicy::push($db,$uid,'mail','New system mail',$subject,'mail:'.$emailId,['email_id'=>$emailId]);$auth->audit('send_root_game_email','email_network',['to_uid'=>$uid,'subject'=>$subject]);$message='Root email queued for in-game delivery.';}}}}}}
$rows=$db->query("SELECT e.email_id,e.to_uid,e.to_address,e.subject,e.delivery_status,e.created_at,u.uname FROM game_email_messages e LEFT JOIN users u ON u.uid=e.to_uid WHERE e.email_type IN ('system','broadcast') ORDER BY e.email_id DESC LIMIT 50");$broadcasts=$db->query('SELECT broadcast_id,subject,recipient_count,created_at FROM game_mail_broadcasts ORDER BY broadcast_id DESC LIMIT 25');$h=static fn($v):string=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Root Email Network</title><link rel="stylesheet" href="/main.css"><style>:root{color-scheme:dark}body{margin:0;background:radial-gradient(circle at 20% 0%,#12324a 0,#06121d 42%,#02070c 100%);font-family:Inter,system-ui,sans-serif;color:#d8f6ff}.admin-shell{max-width:1180px;margin:0 auto;padding:clamp(16px,3vw,34px)}.admin-shell h1{color:#79e9ff;text-decoration:none;letter-spacing:.08em;text-transform:uppercase}.admin-shell h2{color:#b7f5ff;text-decoration:none;font-size:1.1rem;letter-spacing:.05em;text-transform:uppercase}.admin-card{background:linear-gradient(145deg,rgba(10,38,56,.96),rgba(4,16,27,.96));border:1px solid #1b7895;border-left:4px solid #33d7ff;box-shadow:0 0 22px rgba(0,180,255,.12);border-radius:8px;padding:18px;margin:16px 0}.admin-form-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:14px}.admin-form-grid label{display:flex;flex-direction:column;gap:6px;color:#83c9d8;font-size:.82rem;text-transform:uppercase;letter-spacing:.04em}.admin-form-grid label:nth-child(4){grid-column:1/-1}.admin-form-grid input,.admin-form-grid select,.admin-form-grid textarea{box-sizing:border-box;width:100%;padding:10px;border:1px solid #287f99;border-radius:4px;background:#061522;color:#eaffff}.admin-form-grid button,.admin-card button{padding:10px 14px;border:1px solid #43dfff;border-radius:4px;background:#0c4960;color:#eaffff;font-weight:700;cursor:pointer}.admin-form-grid button:hover,.admin-card button:hover{background:#126f8a}.comm-alert{padding:11px 14px;border:1px solid #35d6ff;border-radius:5px;background:#083b4b;color:#d8fbff}.comm-error{border-color:#ff6f91;background:#4a1726}.admin-table-wrap{overflow:auto}.admin-card table{width:100%;border-collapse:collapse}.admin-card th,.admin-card td{padding:9px;border-bottom:1px solid #16495d;text-align:left;white-space:nowrap}.admin-card th{color:#77e7ff;text-transform:uppercase;font-size:.72rem;letter-spacing:.05em}@media(max-width:640px){.admin-shell{padding:12px}.admin-card{padding:13px}.admin-form-grid label:nth-child(4){grid-column:auto}.admin-shell h1{font-size:1.35rem}}</style></head><body><main class="admin-shell"><h1>Root Email Network</h1><p>Command mail relay · Authenticated administrator: <?=$h($auth->admin['username'])?> · <?=$h($auth->admin['role'])?> · Sender: <?=$h(GameEmailPolicy::ROOT_ADDRESS)?></p><?php if($message):?><div class="comm-alert"><?=$h($message)?></div><?php endif;?><?php if($error):?><div class="comm-alert comm-error"><?=$h($error)?></div><?php endif;?><section class="admin-card"><h2>Send targeted system email</h2><p>Attachments are delivered into the commander inbox and claimed once server-side. Currency keys must match the ten-resource economy; item and equipment keys are validated by the mail policy.</p><form method="post" class="admin-form-grid"><input type="hidden" name="csrf" value="<?=$h($csrf)?>"><input type="hidden" name="admin_email_action" value="targeted"><label>Recipient UID<input type="number" name="to_uid" min="1" required></label><label>From address<input type="email" name="from_address" value="<?=$h(GameEmailPolicy::ROOT_ADDRESS)?>" required></label><label>Subject<input name="subject" maxlength="190" required></label><label>Message<textarea name="body" rows="6" maxlength="20000" required></textarea></label><label>Attachment type<select name="attachment_type"><option value="">None</option><option value="currency">Currency</option><option value="item">Item</option><option value="equipment">Equipment</option></select></label><label>Currency key<input name="resource_key" placeholder="metal or dark_matter"></label><label>Item/equipment key<input name="asset_key" placeholder="blueprint.alpha or module:shield"></label><label>Quantity<input type="number" name="quantity" min="1" max="1000000000" value="1"></label><button>Queue Targeted Email</button></form></section><section class="admin-card"><h2>Global server announcement</h2><p>Broadcasts create one inbox message and one notification for every current player.</p><form method="post" class="admin-form-grid"><input type="hidden" name="csrf" value="<?=$h($csrf)?>"><input type="hidden" name="admin_email_action" value="broadcast"><input type="hidden" name="from_address" value="<?=$h(GameEmailPolicy::ROOT_ADDRESS)?>"><label>Subject<input name="subject" maxlength="190" required></label><label>Announcement<textarea name="body" rows="6" maxlength="20000" required></textarea></label><label>Attachment type<select name="attachment_type"><option value="">None</option><option value="currency">Currency</option><option value="item">Item</option><option value="equipment">Equipment</option></select></label><label>Currency key<input name="resource_key" placeholder="metal or dark_matter"></label><label>Item/equipment key<input name="asset_key" placeholder="blueprint.alpha or module:shield"></label><label>Quantity<input type="number" name="quantity" min="1" max="1000000000" value="1"></label><button>Broadcast to All Players</button></form></section><section class="admin-card"><h2>Recent broadcasts</h2><div class="admin-table-wrap"><table><tr><th>ID</th><th>Subject</th><th>Recipients</th><th>Created</th></tr><?php if($broadcasts)while($b=$broadcasts->fetch_assoc()):?><tr><td><?=(int)$b['broadcast_id']?></td><td><?=$h($b['subject'])?></td><td><?=(int)$b['recipient_count']?></td><td><?=$h($b['created_at'])?></td></tr><?php endwhile;?></table></div></section><section class="admin-card"><h2>System mail queue</h2><div class="admin-table-wrap"><table><tr><th>ID</th><th>Recipient</th><th>Subject</th><th>Status</th><th>Created</th></tr><?php if($rows)while($r=$rows->fetch_assoc()):?><tr><td><?=(int)$r['email_id']?></td><td><?=$h($r['uname']?:$r['to_address'])?></td><td><?=$h($r['subject'])?></td><td><?=$h($r['delivery_status'])?></td><td><?=$h($r['created_at'])?></td></tr><?php endwhile;?></table></div></section><p><a href="/admin/">Return to Admin Control Plane</a></p></main></body></html>
